$(\mathcal{A},~\otimes,~I,~a,~l,~r)$ is a monoidal category if for all objects $X$, $Y$, $Z$ and $W$ in $\mathcal{A}$, the associativity pentagon and the unit triangle commute.\\

Here $\mathcal{A}$ is a category, $\otimes:~\mathcal{A} \times \mathcal{A} \rightarrow \mathcal{A}$ is a functor, $I$ is a unit object in $\mathcal{A}$, $a$ is the associativity constraint which is a family of natural isomorphisms 
\begin{align}
\begin{tikzpicture}
\node (A) at (0, 0) {$a_{XYZ}:~(X\otimes Y) \otimes Z$};
\node (B) at (4, 0) {$X\otimes (Y\otimes Z)$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align}

$l$ is a left unit constraint which is a family of natural isomorphisms 
\begin{align}
\begin{tikzpicture}
\node (A) at (0, 0) {$l_X:~I\otimes X$};
\node (B) at (3, 0) {$X$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align}

and $r$ is a right unit constraint which is a family of natural isomorphisms 
\begin{align}
\begin{tikzpicture}
\node (A) at (0, 0) {$r_X:~X\otimes I$};
\node (B) at (3, 0) {$X.$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align}

We define the tensor product as $X\otimes^{op} Y=Y\otimes X$ and associativity constraint $a^{op}$ as a family of natural isomorphisms 
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$a^{op}_{XYZ}:~(X\otimes^{op} Y)\otimes^{op} Z$};
\node (B) at (5.5, 0) {$X\otimes^{op}(Y\otimes^{op} Z)$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align*}

 in $\mathcal{A}^{op}$ for all objects $X$, $Y$ and $Z$ in $\mathcal{A}$. This is same as the family of natural isomorphisms
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$Z\otimes (Y\otimes X)$};
\node (B) at (4, 0) {$(Z\otimes Y) \otimes X$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align*}

in $\mathcal{A}^{op}$ which can be obtained by inverting the arrows 
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$(Z\otimes Y) \otimes X$};
\node (B) at (4, 0) {$Z\otimes (Y\otimes X)$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align*}

in $\mathcal{A}$ and as a result, we get $a^{op}_{XYZ}=a^{-1}_{ZYX}$ for all objects $X$, $Y$ and $Z$ in $\mathcal{A}$.\\

Here, $I^{op}=I$. $l^{op}$ is a left unit constraint which is a family of natural isomorphisms
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$l^{op}_X:~I\otimes^{op} X$};
\node (B) at (3, 0) {$X$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align*}

in $\mathcal{A}^{op}$ which is same as
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$ l^{op}_X:~X\otimes I$};
\node (B) at (3, 0) {$X$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align*} 

for all objects $X$ in $\mathcal{A}$. So, we take $l^{op}_X=r_X$ and $l^{op}=r$ in $\mathcal{A}$. Similarly, we can take $r^{op}=l$.

A monoidal category $\mathcal{A}$ with a braiding $c$ is called symmetric if the composition 
\begin{align}
\xymatrix{ X\otimes Y \ar[rr]^{c_{XY}}  & & Y\otimes X \ar[rr]^{c_{YX}} & & X\otimes Y}
\end{align}

is $id_{X\otimes Y}$ for all objects $X$, $Y$ in $\mathcal{A}$.

Assume that $G$ is an abelian group, $k$ is a field, $(f,~h)$ is an abelian 3 cocycle on $G$ with coefficients in $k$. That is, $f:~G\times G\times G\rightarrow k$ is a normalized 3 cocycle such that 
\begin{align}
f(x,~0,~y)=0,
\end{align}
\begin{align}
f(x,~y,~z)+f(w,~x+y,~z)+f(w,~x,~y)=f(w,~x,~y+z)+f(w+x,~y,~z)
\end{align}

and $h:~G\times G\rightarrow k$ is a function such that 
\begin{align}
f(y,~z,~x)+h(x,~y+z)+f(x,~y,~z)=h(x,~z)+f(y,~x,~z)+h(x,~y),
\end{align}
\begin{align}
-f(z,~x,~y)+h(x+y,~z)-f(x,~y,~z)=h(x,~z)-f(x,~z,~y)+h(y,~z).
\end{align}

Let $\mathcal{A}$ be a category such that the objects are families of $k$ modules $X=\{X_g~|~g\in G\}$ and the arrow between two families $X$, $Y$ is a family $\xymatrix{ \theta=\{X_{g_1}\ar[r]^{\theta_{g_1g_2}} & Y_{g_2}\}}$ where $\theta_{g_1g_2}$ is a $k$ module homomorphism for all $g_1$ and $g_2$ in $G$,
\begin{align}
(X\otimes Y)_g=\underset{g_1+g_2=g}{\Sigma}(X_{g_1}\otimes Y_{g_2})
\end{align}

is the tensor product,
\begin{align}
a_{XYZ}:~(X\otimes Y)\otimes Z\rightarrow X\otimes (Y\otimes Z),\\ a_{XYZ}((x\otimes y)\otimes z)=f(g_1,~g_2,~g_3)x\otimes (y\otimes z)
\end{align}

is the associativity constraint and 
\begin{align}
c_{XY}:~X\otimes Y\rightarrow Y\otimes X,\\ c(x\otimes y)=h(g_1,~g_2)y\otimes x
\end{align}

is the braiding for $x\in X_{g_1}$, $y\in Y_{g_2}$, $z\in Z_{g_3}$. So, this category is a braided monoidal category.

For two monoidal categories $\mathcal{A}$ and $\mathcal{B}$, assume that $\xymatrix{ \mathcal{F}:~\mathcal{A} \ar[r] & \mathcal{B}}$ is a functor, $\gamma$ is the family of natural isomorphisms 
\begin{align}
\begin{tikzpicture}
\node (A) at (0, 0) {$\gamma_{XY}:~\mathcal{F}(X) \otimes \mathcal{F}(Y)$};
\node (B) at (4, 0) {$\mathcal{F}(X\otimes Y)$};
\path[->] (A) edge node [above] {$\cong$} (B); 
\end{tikzpicture}
\end{align} 

for all objects $X$, $Y$ in $\mathcal{A}$, $\xymatrix{ \varphi:~I\ar[r]^{\cong} & \mathcal{F}(I)}$ is an isomorphism for the unit object $I$. Then, $(\mathcal{F},~\gamma,~\varphi)$ is a monoidal functor if it satisfies compatible conditions.

A monoidal functor $\mathcal{F}:~\mathcal{A} \rightarrow \mathcal{B}$ between braided monoidal categories $\mathcal{A}$ and $\mathcal{B}$ is braided if the following diagram is commutative.
\begin{equation}
\xymatrix{ \mathcal{F}(X) \otimes \mathcal{F}(Y) \ar[d]^c \ar[r]^{\gamma} & \mathcal{F}(X\otimes Y) \ar[d]^{\mathcal{F}(c)}\\ \mathcal{F}(Y) \otimes \mathcal{F}(X) \ar[r]^{\gamma} & \mathcal{F}(Y\otimes X) }
\end{equation}

If $\mathcal{F},~\mathcal{G}:~\mathcal{A} \rightarrow \mathcal{B}$ are two monoidal functors, then a map $\theta:~\mathcal{F} \rightarrow \mathcal{G}$ is a natural transformation if the following two diagrams commute.
\begin{equation}
\xymatrix@C+1em { \mathcal{F}(X) \otimes \mathcal{F}(Y) \ar[d]^{\theta(X) \otimes \theta(Y)} \ar[r]^{\gamma} & \mathcal{F}(X\otimes Y) \ar[d]^{\theta(X\otimes Y)}\\ \mathcal{G}(X) \otimes \mathcal{G}(Y) \ar[r]^{\gamma} & \mathcal{G}(X\otimes Y) } \quad \xymatrix{ & I \ar[ld]_{\varphi} \ar[rd]^{\varphi}\\ \mathcal{F}(I) \ar[rr]^{\theta(I)} & & \mathcal{G}(I) }
\end{equation}

We define a monoidal functor $\mathcal{F}:~\mathcal{A} \rightarrow \mathcal{A}^{rev}$ by sending an object $A$ in $\mathcal{A}$ to itself, $\gamma$ as a family of natural isomorphisms $\gamma_{XY}:~X\otimes^{rev} Y=Y\otimes X \rightarrow X\otimes Y$ for all objects $X$, $Y$ in $\mathcal{A}$ and also $\varphi=id_I$. We define $\gamma_{XY}=c^{rev}_{XY}$. Then, we need to show that the following diagram commutes in $\mathcal{A}^{rev}$.
\begin{align}
\label{354}
\xymatrix{ (X\otimes^{rev} Y)\otimes^{rev} Z \ar[d]_{\gamma \otimes^{rev} id} \ar[r]^{a_{XYZ}^{rev}} & X\otimes^{rev} (Y\otimes^{rev} Z) \ar[d]^{id\otimes^{rev} \gamma} \\ (X\otimes Y)\otimes^{rev} Z\ar[d]_{\gamma} & X\otimes^{rev} (Y\otimes Z) \ar[d]^{\gamma} & &\\ (X\otimes Y)\otimes Z\ar[r]_{a_{XYZ}} & X\otimes (Y\otimes Z)}
\end{align}

This diagram is same as the following diagram in $\mathcal{A}$.
\begin{align}
\label{400}
\xymatrix{ Z\otimes (Y\otimes X) \ar[d]_{id_Z\otimes c_{YX}} \ar[r]^{a^{-1}_{ZYX}} & (Z\otimes Y) \otimes X\ar[d]^{c_{ZY}\otimes id_X} \\ Z\otimes (X\otimes Y) \ar[d]_{c_{Z(XY)}} & (Y\otimes Z) \otimes X \ar[d]^{c_{(YZ)X}} & & \\ (X\otimes Y)\otimes Z \ar[r]_{a_{XYZ}} & X\otimes (Y\otimes Z)}
\end{align}

The first and third squares commute by definition and the middle one commutes by using naturality of the braiding in the following diagram.
\begin{align}
\label{353}
\begin{tikzpicture}
\node (A) at (0, 0) {$(Z\otimes Y)\otimes X$};
\node (B) at (4, 0) {$(Y\otimes Z)\otimes X$};
\node (C) at (8, 0) {$Y\otimes (Z\otimes X)$};
\node (D) at (12, 0) {$Y\otimes (X\otimes Z)$};
\node (E) at (0, -2) {$Z\otimes (Y\otimes X)$};
\node (F) at (12, -2) {$(Y\otimes X)\otimes Z$};
\node (G) at (0, -4) {$Z\otimes (X\otimes Y)$};
\node (H) at (12, -4) {$(X\otimes Y)\otimes Z$};
\node (K) at (0, -6) {$(Z\otimes X)\otimes Y$};
\node (L) at (4, -6) {$(X\otimes Z)\otimes Y)$};
\node (M) at (8, -6) {$X\otimes (Z\otimes Y)$};
\node (N) at (12, -6) {$X\otimes (Y\otimes Z)$};
\path[->] (A) edge node [above] {$c_{ZY}\otimes id_X$} (B);
\path[->] (B) edge node [above] {$a_{YZX}$} (C);
\path[->] (C) edge node [above] {$id_Y\otimes c_{ZX}$} (D);
\path[->] (E) edge node [above] {$c_{Z(YX)}$} (F);
\path[->] (G) edge node [above] {$c_{Z(XY)}$} (H);
\path[->] (K) edge node [below] {$c_{ZX}\otimes id_Y$} (L);
\path[->] (L) edge node [below] {$a_{XZY}$} (M);
\path[->] (M) edge node [below] {$id_X\otimes c_{ZY}$} (N);
\path[->] (A) edge node [left] {$a_{ZYX}$} (E);
\path[->] (E) edge node [left] {$id_Z\otimes c_{YX}$} (G);
\path[->] (G) edge node [left] {$a^{-1}_{ZXY}$} (K);
\path[->] (D) edge node [right] {$a^{-1}_{YXZ}$} (F);
\path[->] (F) edge node [right] {$c_{YX}\otimes id_Z$} (H);
\path[->] (H) edge node [right] {$a_{XYZ}$} (N);
\end{tikzpicture}
\end{align}

As a result, that diagram commutes.\\

$a_{XYZ}\circ c_{Z(XY)}\circ (id_Z\otimes c_{YX})=a_{XYZ}\circ a^{-1}_{XYZ}\circ (id_X\otimes c_{ZY})\circ a_{XZY}\circ (c\otimes id_Y)\circ a^{-1}_{ZXY}\circ (id_Z\otimes c_{YX})=(id_X\otimes c_{ZY})\circ a_{XZY}\circ (c\otimes id_Y)\circ a^{-1}_{ZXY}\circ (id_Z\otimes c_{YX})$.\\

$c_{(YZ)X}\circ (c_{ZY}\otimes id_X)\circ a^{-1}_{ZYX}=a_{XYZ}\circ (c_{YX}\otimes id_Z)\circ a^{-1}_{YXZ}\circ (id_Y\otimes c_{ZX})\circ a_{YZX}\circ (c_{ZY}\otimes id_X)\circ a^{-1}_{ZYX}$.\\

These two equations are same by the commutativity of Diagram \ref{353}. As a result, Diagram \ref{354} commutes. The commutativity of other diagrams are easy to show, also it is a braided monoidal functor. The reader can show that the conditions for equivalence are satisfied.

For a given finite dimensional $k$ vector space $V$, the right and left dual object for $V$ is the dual space $Hom_k(V,~k)$ with the evaluation map 
\begin{align*}
ev_{rV}:~Hom_k(V,~k)\otimes V\rightarrow k,~(f,~v)\mapsto f(v)
\end{align*}

and the coevaluation map $coev_{rV}:~k\rightarrow V\otimes Hom_k(V,~k)$ which is an embedding. We may see that the following compositions are the identities.
\begin{align*}
\begin{tikzpicture}
\node (A) at (0,0) {$V=k\otimes V$};
\node (B) at (6,0) {$V\otimes Hom_k(V,~k)\otimes V$};
\node (C) at (12,0) {$V\otimes k=V$};
\path[->] (A) edge [left] node [above] {$coev_{rV}\otimes id_V$} (B);
\path[->] (B) edge [right] node [above] {$id_V\otimes ev_{rV}$} (C);
\end{tikzpicture}
\end{align*}
\begin{align*}
\begin{tikzpicture}
\node (A) at (0,0) {$Hom_k(V,~k)\otimes k$};
\node (B) at (6,0) {$Hom_k(V,~k)\otimes V\otimes Hom_k(V,~k)$};
\node (C) at (12,0) {$k\otimes Hom_k(V,~k)$};
\node (D) at (0,-2) {$Hom_k(V,~k)$};
\node (E) at (6, -2) {$Hom_k(V,~k)\otimes V\otimes Hom_k(V,~k)$};
\node (F) at (12,-2) {$Hom_k(V,~k)$};
\draw[thick, double] (0, -0.2)--(0, -1.8) [xshift=5pt];
\draw[thick, double] (12, -0.2)--(12, -1.8) [xshift=5pt];
\path[->] (A) edge [left] node [above] {$id\otimes coev_{rV}$} (B);
\path[->] (B) edge [right] node [above] {$ev_{rV}\otimes id$} (C);
\path[->] (D) edge [left] node [above] {$id\otimes coev_{rV}$} (E);
\path[->] (E) edge [right] node [above] {$ev_{rV}\otimes id$} (F);
\end{tikzpicture}
\end{align*}

Similarly, we may show that the compositions \ref{98} and \ref{99} are the identities which shows that $Hom_k(V,~k)$ is a left dual for the object $V$.\\

Second part follows since infinite dimensional spaces don't have any coevaluation map.

If $X$ is an object in a rigid monoidal category $\mathcal{A}$, then $X$ has both a left and a right dual objects $^+X$ and $X^+$ which are unique up to a unique isomorphism by Lemma \ref{96} such that the following compositions are the identities by definition where $ev_{rX}:~X_+\otimes X \rightarrow I$, $coev_{rX}:~I \rightarrow X\otimes X^+$, $ev_{lX}:~X\otimes {^+X}\rightarrow I$ and  $coev_{lX}:~I \rightarrow {^+X}\otimes X$  are morphisms in $\mathcal{A}$.
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$X^+=X^+\otimes I$};
\node (B) at (6, 0) {$X^+\otimes X\otimes X^+$};
\node (C) at (12, 0) {$I\otimes X^+=X^+$};
\path[->] (A) edge node [above] {$id_{X^+}\otimes coev_{rX}$} (B); 
\path[->] (B) edge node [above] {$ev_{rX}\otimes id_{X^+}$} (C); 
\end{tikzpicture}
\\
\begin{tikzpicture}
\node(A) at (0, 0) {$X=I\otimes X$};
\node (B) at (6, 0) {$X\otimes X^+\otimes X$};
\node (C) at (12, 0) {$X\otimes I=X$};
\path[->] (A) edge node [above] {$coev_{rZ}\otimes id_X$} (B);
\path[->] (B) edge node [above]{$id_X\otimes ev_{rX}$} (C);
\end{tikzpicture}
\\
\begin{tikzpicture}
\node (A) at (0, 0) {$^+X=I\otimes {^+X}$};
\node (B) at (6, 0) {$^+X\otimes X \otimes {^+X}$};
\node (C) at (12, 0) {$ ^+X\otimes I={^+X}$};
\path[->] (A) edge node [above] {$coev_{lX}\otimes id_{^+X}$} (B); 
\path[->] (B) edge node [above] {$id_{^+X}\otimes ev_{lX}$} (C); 
\end{tikzpicture}
\\
\begin{tikzpicture}
\node (A) at (0, 0) {$X=X\otimes I$};
\node (B) at (6, 0) {$X\otimes {^+X} \otimes X$};
\node (C) at (12, 0) {$I\otimes X=X$};
\path[->] (A) edge node [above] {$id_X\otimes coev_{lX}$} (B); 
\path[->] (B) edge node [above] {$ev_{lX}\otimes id_X$} (C); 
\end{tikzpicture}
\end{align*}

We know that $ev_{rX}\otimes id_{X^+} \circ id_{X^+}\otimes coev_{rX}=id_{X^+}$ in $\mathcal{A}$ by the first composition, so $(ev_{rX}\otimes id_{X^+} \circ id_{X^+}\otimes coev_{rX})^{op}=(id_{X^+})^{op}=id_{X^+}$. This implies that 
\begin{align*}
(id_{X^+}\otimes coev_{rX})^{op}\circ (ev_{rX}\otimes id_{X^+})^{op}=coev_{rX}^{op}\otimes ^{op} id_{X^+}\circ id_{X^+}\otimes ^{op} ev_{rX}^{op}=id_{X^+}.
\end{align*}

As a result, the following composition is the identity of $X^+$ in $\mathcal{A}^{op}$
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$X^+=I\otimes X^+$};
\node (B) at (6, 0) {$X^+\otimes X \otimes X^+$};
\node (C) at (12, 0) {$X^+\otimes I=X^+$};
\path[->] (A) edge node [above] {$id_{X^+}\otimes^{op} ev_{rX}^{op}$} (B); 
\path[->] (B) edge node [above] {$coev_{rX}^{op}\otimes^{op} id_{X^+}$} (C); 
\end{tikzpicture}
\end{align*}

which is same as the following one
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$X^+=X^+\otimes^{op} I $};
\node (B) at (6, 0) {$ X^+\otimes^{op} X \otimes^{op} X^+$};
\node (C) at (12, 0) {$I\otimes^{op} X^+=X^+.$};
\path[->] (A) edge node [above] {$id_{X^+}\otimes^{op} ev_{rX}^{op}$} (B); 
\path[->] (B) edge node [above] {$coev_{rX}^{op}\otimes^{op} id_{X^+}$} (C); 
\end{tikzpicture}
\end{align*}

Also, we get an identity of $X$ by the composition
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$X=X\otimes I$};
\node (B) at (6, 0) {$X\otimes X^+\otimes X$};
\node (C) at (12, 0) {$ I\otimes X=X$};
\path[->] (A) edge node [above] {$(id_X\otimes ev_{rX})^{op}$} (B); 
\path[->] (B) edge node [above] {$(coev_{rX}\otimes id_X)^{op}$} (C); 
\end{tikzpicture}
\end{align*}

which is same as the following one
\begin{align*}
\begin{tikzpicture}
\node (A) at (0, 0) {$X=I\otimes^{op} X$};
\node (B) at (6, 0) {$X\otimes^{op} X^+\otimes^{op} X$};
\node (C) at (12, 0) {$X\otimes^{op} I=X.$};
\path[->] (A) edge node [above] {$ev_{rX}^{op}\otimes^{op} id_X$} (B); 
\path[->] (B) edge node [above] {$id_X\otimes^{op} coev_{rX}^{op}$} (C); 
\end{tikzpicture}
\end{align*}

These two identities show that $X^+$ is right dual for $X$ in $\mathcal{A}^{op}$. By using same technique, we may show that $^+X$ is left dual for $X$ in $\mathcal{A}^{op}$. Those are unique objects in $\mathcal{A}$ by Lemma \ref{96}, so they are also unique in $\mathcal{A}^{op}$ as objects. This shows that $\mathcal{A}^{op}$ is a rigid category.

We define the evaluation map as $ev_{r\mathcal{F}(X)}=\mathcal{F}(ev_{rX}) \circ \gamma$ that is shown with the following diagram
\begin{align*}
ev_{r\mathcal{F}(X)}:~\mathcal{F}(X^+)\otimes \mathcal{F}(X)\rightarrow \mathcal{F}(X^+\otimes X) \rightarrow \mathcal{F}(I)
\end{align*}

and the coevaluation map as $coev_{r\mathcal{F}(X)}=\gamma^{-1} \circ \mathcal{F}(coev_{rX})$ that is shown with the following diagram
\begin{align*}
coev_{r\mathcal{F}(X)}:~\mathcal{F}(I) \rightarrow \mathcal{F}(X\otimes  X^+) \rightarrow \mathcal{F}(X) \otimes \mathcal{F}(X^+)
\end{align*}

by using $\gamma$. It is obvious that the following compositions are the identities since $\mathcal{F}$ is a monoidal functor and $X^+$ is a right dual for $X$.
\begin{align*}
\xymatrix{ \mathcal{F}(X^+)=\mathcal{F}(X^+) \otimes \mathcal{F}(I) \ar[r] & \mathcal{F}(X^+) \otimes \mathcal{F}(X) \otimes \mathcal{F}(X^+) \ar[r] & \mathcal{F}(I) \otimes \mathcal{F}(X^+)=\mathcal{F}(X^+)}\\
\xymatrix{ \mathcal{F}(X)=\mathcal{F}(I) \otimes \mathcal{F}(X) \ar[r] & \mathcal{F}(X) \otimes \mathcal{F}(X^+) \otimes \mathcal{F}(X) \ar[r] & \mathcal{F}(X) \otimes \mathcal{F}(I)=\mathcal{F}(X)}
\end{align*}

As a result, $\mathcal{F}(X^+)$ is a right dual for $\mathcal{F}(X)$.

$(Z,~\gamma_Z)\otimes (W,~\gamma_W)=(Z\otimes W,~(\gamma_Z \otimes id_W)\circ (id_Z\otimes \gamma_W))$ is a tensor product for all objects $Z$ and $W$ in $\mathcal{A}$ and $c_{(Z,~\gamma_Z)(W,~\gamma_W)}: (Z,~\gamma_Z)\otimes (W,~\gamma_W) \rightarrow (W,~\gamma_W)\otimes (Z,~\gamma_Z)$ is a braiding which is same as 
\begin{align*}
c:~(Z\otimes W,~(\gamma_Z \otimes id_W) \circ (id_Z\otimes \gamma_W)) \rightarrow (W\otimes Z,~(\gamma_W \otimes id_Z)\circ (id_W\otimes \gamma_Z)).
\end{align*}

\cite{os} A category $\mathcal{M}$ is a left module category on a finite monoidal category $\mathcal{A}$ if there exists an exact bifunctor
\begin{align}
\label{74}
\otimes_{l\mathcal{M}}:~\mathcal{A} \times \mathcal{M} \rightarrow \mathcal{M},~(X,~M)\mapsto X\otimes_{l\mathcal{M}} M
\end{align}

for all objects $X$ in $\mathcal{A}$, $M$ in $\mathcal{M}$, associativity constraint $a_{l\mathcal{M}}$ consisting of associativity isomorphisms $a_{XYM}: (X\otimes_{\mathcal{A}} Y)\otimes_{l\mathcal{M}} M\rightarrow X\otimes_{l\mathcal{M}}(Y\otimes_{l\mathcal{M}} M)$ and left unit constraint $l_{\mathcal{M}}$ which is a family of left unit isomorphisms $l_M:~I\otimes_{l\mathcal{M}} M\rightarrow M$ such that for any $X$, $Y$, $Z$ in $\mathcal{A}$, $M$ in $\mathcal{M}$, the following diagrams commute.
\begin{align}
\begin{tikzpicture}
\node (A) at (0, 0) {$((X\otimes_{\mathcal{A}} Y)\otimes_{\mathcal{A}} Z)\otimes_{l\mathcal{M}} M$};
\node (B) at (8, 0) {$(X\otimes_{\mathcal{A}} (Y\otimes_{\mathcal{A}} Z))\otimes_{l\mathcal{M}} M$};
\node (C) at (-1, -2) {$(X\otimes_{\mathcal{A}} Y)\otimes_{l\mathcal{M}} (Z\otimes_{l\mathcal{M}} M) $};
\node (D) at (9, -2) {$X\otimes_{l\mathcal{M}} ((Y\otimes_{\mathcal{A}} Z)\otimes_{l\mathcal{M}} M)$};
\node (E) at (4, -4) {$X\otimes_{l\mathcal{M}} (Y\otimes_{l\mathcal{M}} (Z\otimes_{l\mathcal{M}} M))$};
\draw [->, thick] (4.8, -1.5) arc (360:30:20pt);
\path[->] (A) edge node [above] {$a_{XYZ}\otimes_{l\mathcal{M}} id_M$} (B);
\path[->] (A) edge node [left, midway] {$a_{(XY)ZM}$} (C);
\path[->] (B) edge node [right, midway] {$a_{X(YZ)M}$} (D);
\path[->] (C) edge node [left, midway] {$a_{XY(ZM)}$} (E);
\path[->] (D) edge node [right, midway] {$id_X\otimes_{l\mathcal{M}} a_{YZM}$} (E);
\end{tikzpicture}
\end{align}
\begin{align}
\begin{tikzpicture}
\node (A) at (0, 0) {$(X\otimes_{\mathcal{A}} I)\otimes_{l\mathcal{M}} M$};
\node (B) at (6, 0) {$ X\otimes_{l\mathcal{M}} (I\otimes_{l\mathcal{M}} M)$};
