For all $a,~a'\in M_1$, $b\in N_1$ and $c\in N_2$, $d,~d'\in M_2$, we get the following equalities by definition of $\gamma_1$ and $\gamma_2$.
\begin{enumerate}
\item \label{60} $\gamma_1(a.a')=(^{f_1(a')}\gamma_1(a)). \gamma_1(a')$
\item $g_1(a)=f_1(a). h_{\mathfrak{C_2}}(\gamma_1(a^{-1}))$
\item $g_2(b)=f_2(b). \gamma_1(h_{\mathfrak{C_1}}(b^{-1}))$
\item \label{61} $\gamma_2(d.d')=(^{k_1(d')}\gamma_2(d)). \gamma_2(d')$
\item $e_1(d)=k_1(d). h_{\mathfrak{C_3}}(\gamma_2(d^{-1}))$
\item \label{65} $e_2(c)=k_2(c). \gamma_2(h_{\mathfrak{C_2}}(c^{-1}))$
\end{enumerate}

For all $a'\in M_1$, we have 
\begin{align}
\label{63}
(k_1\circ g_1)(a')=k_1(f_1(a'). h_{\mathfrak{C_2}}(\gamma_1((a')^{-1})))=(k_1\circ f_1)(a'). (k_1\circ h_{\mathfrak{C_2}})(\gamma_1((a')^{-1})),
\end{align}
\begin{align}
(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)((a')^{-1}))=k_2(^{f_1(a')}\gamma_1((a')^{-1}))\\
=k_2((^{f_1(a')}\gamma_1((a')^{-1})). \gamma_1(a'). \gamma_1((a')^{-1}))\\
\label{62} 
=k_2((a')^{-1}. a' . \gamma_1((a')^{-1}))=(k_2\circ \gamma_1)((a')^{-1}).
\end{align}

For all $a,~a'\in M_1$, we have\\

$\gamma_3(a . a')=(k_2\circ \gamma_1)(a.a') . (\gamma_2 \circ g_1)(a. a')=k_2((^{f_1(a')}\gamma_1(a)). \gamma_1(a')) . \gamma_2(g_1(a) . g_1(a'))$ by \ref{60}\\

$=k_2(^{f_1(a')}\gamma_1(a)). k_2(\gamma_1(a')). (^{(k_1\circ g_1)(a')}(\gamma_2 \circ g_1)(a)) . (\gamma_2 \circ g_1)(a')$ by \ref{61}\\

$=k_2(^{f_1(a')}\gamma_1(a)). k_2(\gamma_1(a')). (^{(k_1\circ f_1)(a'). k_1(h_{\mathfrak{C_2}}(\gamma_1((a')^{-1})))}(\gamma_2\circ g_1)(a)) . (\gamma_2 \circ g_1)(a')$ by \ref{63}\\

$=k_2(^{f_1(a')}\gamma_1(a)). k_2(\gamma_1(a')). (^{(k_1\circ f_1)(a'). (h_{\mathfrak{C_3}} (k_2\circ \gamma_1)((a')^{-1}))}(\gamma_2\circ g_1)(a)) . (\gamma_2 \circ g_1)(a')$ since $K$ is a strict morphism\\

$=k_2(^{f_1(a')}\gamma_1(a)). k_2(\gamma_1(a')). (^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)((a')^{-1}).(\gamma_2\circ g_1)(a). (k_2\circ \gamma_1)(a')). (\gamma_2 \circ g_1)(a')$ by definition of $\mathfrak{C_3}$\\

$=k_2(^{f_1(a')}\gamma_1(a)). k_2(\gamma_1(a')). (^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)((a')^{-1})) .(^{(k_1\circ f_1)(a')}(\gamma_2\circ g_1)(a)).\\
(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a')). (\gamma_2 \circ g_1)(a')$\\

$=(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a)).k_2(\gamma_1(a')). (^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)((a')^{-1})) .(^{(k_1\circ f_1)(a')}(\gamma_2\circ g_1)(a)).\\
(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a')). (\gamma_2 \circ g_1)(a')$ since $K$ is a strict morphism\\

$=(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a)). k_2(\gamma_1(a')). (k_2\circ \gamma_1)((a')^{-1}). (^{(k_1\circ f_1)(a')}(\gamma_2\circ g_1)(a)).\\
(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a')). (\gamma_2 \circ g_1)(a')$ by \ref{62}\\

$=(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a)). (^{(k_1\circ f_1)(a')}(\gamma_2\circ g_1)(a)). (^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a')). (\gamma_2 \circ g_1)(a')$\\

$=(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a)). (^{(k_1\circ f_1)(a')}(\gamma_2\circ g_1)(a)). (k_2\circ \gamma_1)(a'). (\gamma_2 \circ g_1)(a')$ by \ref{62}\\

$=(^{(k_1\circ f_1)(a')}(k_2\circ \gamma_1)(a). (\gamma_2\circ g_1)(a)) . (k_2\circ \gamma_1)(a'). (\gamma_2 \circ g_1)(a')$\\

$=(^{(k_1\circ f_1)(a')}((k_2\circ \gamma_1). (\gamma_2\circ g_1))(a)). ((k_2\circ \gamma_1) . (\gamma_2 \circ g_1))(a')$\\

$=(^{(k_1\circ f_1)(a')}\gamma_3(a)). \gamma_3(a')$ as required.\\

The other conditions are satisfied.\\

For a crossed homomorphism $\xymatrix{\mathfrak{C}=[N\ar[r]^{h_{\mathfrak{C}}} & M]}$, the mapping $\mathcal{F}_{\mathfrak{C}}:~1\rightarrow \underline{\mathcal{XM}}(\mathfrak{C},~\mathfrak{C})$ is a functor taking the element $\star$ in $1$ to $id_h=(id,~id)$ and morphisms $\star \rightarrow \star$ to a trivial pointed natural transformation $PNT:~(id,~id)\Rightarrow (id,~id)$.
